// <auto-generated/>
using JO.DataModel.Entity;
using JO.DataModel.View;
using JO.Service.Constants;
using JO.Service.Services.Contracts;
using Microsoft.AspNetCore.Components;

namespace JO.BlazorDemoApp.Components.Pages.Admin.User
{
    public partial class NewUser
    {
        [Inject] private IManageUsersService ManageUsersService { get; set; } = default!;
        [Inject] private IAccountService AccountService { get; set; } = default!;
        [Inject] private IUtilitiesService UtilitiesService { get; set; } = default!;
        [Inject] private IAlertService AlertService { get; set; } = default!;
        [Inject] private NavigationManager Navigation { get; set; } = default!;

        private List<VwJOUserAspNetRoles> roles = new();
        private List<string> roleNames = new();
        private JobOfferUsers newUser = new();
        private int userId = 0;

        protected override async Task OnInitializedAsync()
        {
            roles = await ManageUsersService.GetVwJOUserAspNetRoles();

            newUser.IsActive = true;
            newUser.CreatedBy = await AccountService.GetJobOfferUserId();
        }

        private async Task SaveUser()
        {
            var errors = await CollectErrors();

            if (errors.Count > 0)
            {
                await AlertService.Errors(errors);
                return;
            }

            await AlertService.Confirm("Save this user?", "Save");

            var joUserId = await ManageUsersService.CreateJobOfferUser(newUser, roleNames);
            Navigation.NavigateTo($"{JORoutes.Admin.UserDetails}/{joUserId}");
        }

        private async Task<List<string>> CollectErrors()
        {
            var errors = new List<string>();

            if (string.IsNullOrWhiteSpace(newUser.Name))
                errors.Add("Name is required.");

            var isValidEmail = UtilitiesService.IsValidEmail(newUser.Email ?? string.Empty);

            if (!isValidEmail)
                errors.Add("Please enter a valid email address.");

            if (isValidEmail && await ManageUsersService.IsUserExists(newUser.Email!))
                errors.Add("User already exists.");

            if (roleNames.Count == 0)
                errors.Add("Please select at least one role.");

            return errors;
        }

        private bool AreAllRolesSelected
        {
            get
            {
                var selectableRoleNames = GetSelectableRoleNames();
                return selectableRoleNames.Count > 0 && selectableRoleNames.All(roleNames.Contains);
            }
        }

        private bool IsRoleSelected(string? roleName)
        {
            return !string.IsNullOrWhiteSpace(roleName)
                && roleNames.Contains(roleName);
        }

        private void ToggleRole(string? roleName, ChangeEventArgs eventArgs)
        {
            if (string.IsNullOrWhiteSpace(roleName))
                return;

            var isChecked = eventArgs.Value is bool value && value;

            if (isChecked)
            {
                if (!roleNames.Contains(roleName))
                    roleNames.Add(roleName);
            }
            else
            {
                roleNames.Remove(roleName);
            }
        }

        private void ToggleAllRoles(ChangeEventArgs eventArgs)
        {
            var selectableRoleNames = GetSelectableRoleNames();
            var isChecked = eventArgs.Value is bool value && value;

            if (isChecked)
            {
                foreach (var roleName in selectableRoleNames)
                {
                    if (!roleNames.Contains(roleName))
                        roleNames.Add(roleName);
                }
            }
            else
            {
                roleNames.RemoveAll(selectableRoleNames.Contains);
            }
        }

        private List<string> GetSelectableRoleNames()
        {
            return roles
                .Where(role => role.IsActive == true && !string.IsNullOrWhiteSpace(role.RoleName))
                .Select(role => role.RoleName!)
                .Distinct()
                .ToList();
        }
    }
}
